"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[31025],{3331:(e,r,n)=>{n.d(r,{R:()=>o,x:()=>l});var t=n(36672);const i={},s=t.createContext(i);function o(e){const r=t.useContext(s);return t.useMemo((function(){return"function"==typeof e?e(r):{...r,...e}}),[r,e])}function l(e){let r;return r=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:o(e.components),t.createElement(s.Provider,{value:r},e.children)}},97259:(e,r,n)=>{n.r(r),n.d(r,{assets:()=>a,contentTitle:()=>l,default:()=>g,frontMatter:()=>o,metadata:()=>t,toc:()=>k});const t=JSON.parse('{"id":"2023/04/10","title":"2023-04-10","description":"LLama-effekten: Lekkasje utl\xf8ste en rekke \xe5pen kildekode-alternativer til ChatGPT","source":"@site/i18n/nb/docusaurus-plugin-content-docs/current/2023/04/10.md","sourceDirName":"2023/04","slug":"/2023/04/10","permalink":"/nb/2023/04/10","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/nb/docusaurus-plugin-content-docs//current/2023/04/10.md","tags":[],"version":"current","frontMatter":{"localized_date":"10. april 2023","top_news":"LLama-effekten: Lekkasje utl\xf8ste en rekke \xe5pen kildekode-alternativer til ChatGPT"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-11","permalink":"/nb/2023/04/11"},"next":{"title":"2023-04-09","permalink":"/nb/2023/04/09"}}');var i=n(23420),s=n(3331);const o={localized_date:"10. april 2023",top_news:"LLama-effekten: Lekkasje utl\xf8ste en rekke \xe5pen kildekode-alternativer til ChatGPT"},l="2023-04-10",a={},k=[{value:"LLama-effekten: Lekkasje utl\xf8ste en rekke \xe5pen kildekode-alternativer til ChatGPT",id:"llama-effekten-lekkasje-utl\xf8ste-en-rekke-\xe5pen-kildekode-alternativer-til-chatgpt",level:2},{value:"Fra dyp til lang l\xe6ring?",id:"fra-dyp-til-lang-l\xe6ring",level:2},{value:"EY blir utestengt fra ny revisjonsvirksomhet i Tyskland.",id:"ey-blir-utestengt-fra-ny-revisjonsvirksomhet-i-tyskland",level:2},{value:"Solnedgang p\xe5 Sydpolen",id:"solnedgang-p\xe5-sydpolen",level:2},{value:"En nederlandsk journalist som skriver kritisk om Kina som m\xe5l for skremselspropaganda.",id:"en-nederlandsk-journalist-som-skriver-kritisk-om-kina-som-m\xe5l-for-skremselspropaganda",level:2},{value:"USPS&#39; anlegg i Utah gj\xf8r ikke annet enn \xe5 tyde h\xe5ndskrift.",id:"usps-anlegg-i-utah-gj\xf8r-ikke-annet-enn-\xe5-tyde-h\xe5ndskrift",level:2},{value:"Apple fortsetter innsatsen for \xe5 hindre at butikker fagorganiserer seg.",id:"apple-fortsetter-innsatsen-for-\xe5-hindre-at-butikker-fagorganiserer-seg",level:2},{value:"PL/Rust 1.0: n\xe5 et p\xe5litelig spr\xe5k for Postgres",id:"plrust-10-n\xe5-et-p\xe5litelig-spr\xe5k-for-postgres",level:2},{value:"Twitter blokkerer likes og retweets som nevner Substack.",id:"twitter-blokkerer-likes-og-retweets-som-nevner-substack",level:2},{value:"Z-Library skal la brukerne dele fysiske b\xf8ker.",id:"z-library-skal-la-brukerne-dele-fysiske-b\xf8ker",level:2},{value:"Perseus - NextJS alternativ i Rust",id:"perseus---nextjs-alternativ-i-rust",level:2},{value:"En baby-GPT",id:"en-baby-gpt",level:2},{value:"To typer programvareingeni\xf8rer",id:"to-typer-programvareingeni\xf8rer",level:2},{value:"Avansert Linux-programmering (2001)",id:"avansert-linux-programmering-2001",level:2},{value:"Et CERN for \xe5pen kildekode for storskala AI",id:"et-cern-for-\xe5pen-kildekode-for-storskala-ai",level:2},{value:"Permafrost-motoren - en OpenGL RTS-spillmotor skrevet i C.",id:"permafrost-motoren---en-opengl-rts-spillmotor-skrevet-i-c",level:2},{value:"Lukke en foreldet SSH-tilkobling.",id:"lukke-en-foreldet-ssh-tilkobling",level:2},{value:"Flatcar Container Linux",id:"flatcar-container-linux",level:2},{value:"Microsoft / JARVIS: et system for \xe5 koble LLM-er med ML-fellesskapet",id:"microsoft--jarvis-et-system-for-\xe5-koble-llm-er-med-ml-fellesskapet",level:2},{value:"Sf\xe6risk tokamak oppn\xe5r avgj\xf8rende plasmatemperaturer",id:"sf\xe6risk-tokamak-oppn\xe5r-avgj\xf8rende-plasmatemperaturer",level:2},{value:"De f\xf8rste &quot;p\xe5skeeggene&quot; var et oppr\xf8r fra bedriftens side.",id:"de-f\xf8rste-p\xe5skeeggene-var-et-oppr\xf8r-fra-bedriftens-side",level:2},{value:"Modul\xe6re feil i Rust",id:"modul\xe6re-feil-i-rust",level:2},{value:"68-95-99.7 Regel",id:"68-95-997-regel",level:2},{value:"UnicodePlots",id:"unicodeplots",level:2},{value:"Digitale samleobjekter p\xe5 Instagram er i ferd med \xe5 avvikles",id:"digitale-samleobjekter-p\xe5-instagram-er-i-ferd-med-\xe5-avvikles",level:2},{value:"Dommen som truer bibliotekenes fremtid Dommen som truer bibliotekenes fremtid",id:"dommen-som-truer-bibliotekenes-fremtid-dommen-som-truer-bibliotekenes-fremtid",level:2},{value:"Do Kwon konverterte ulovlige midler fra LUNA til Bitcoin.",id:"do-kwon-konverterte-ulovlige-midler-fra-luna-til-bitcoin",level:2},{value:"Intervju med Andrew Kelley (Zig Creator) (2021) (engelsk)",id:"intervju-med-andrew-kelley-zig-creator-2021-engelsk",level:2},{value:"Vis Supavisor - en Postgres-tilkoblingspool skrevet i Elixir.",id:"vis-supavisor---en-postgres-tilkoblingspool-skrevet-i-elixir",level:2},{value:"Nye beskyldninger om plagiering mot Roy Lichtenstein.",id:"nye-beskyldninger-om-plagiering-mot-roy-lichtenstein",level:2}];function d(e){const r={a:"a",del:"del",h1:"h1",h2:"h2",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(r.header,{children:(0,i.jsx)(r.h1,{id:"2023-04-10",children:"2023-04-10"})}),"\n",(0,i.jsx)(r.h2,{id:"llama-effekten-lekkasje-utl\xf8ste-en-rekke-\xe5pen-kildekode-alternativer-til-chatgpt",children:"LLama-effekten: Lekkasje utl\xf8ste en rekke \xe5pen kildekode-alternativer til ChatGPT"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://thesequence.substack.com/p/the-llama-effect-how-an-accidental",children:"Original"}),'.\nDen utilsiktede lekkasjen av "Llama", en LLM-modell, har utl\xf8st en alternativ bevegelse med \xe5pen kildekode til modeller som GPT-4 og Cohere som bare er tilgjengelige via API-er. Siden lekkasjen har Alpaca, Vicuna, Koala, ColossalChat og ChatLLama, blant andre modeller, blitt utgitt, alle bygget p\xe5 toppen av Llama. Alternativene med \xe5pen kildekode til disse modellene har ikke vist samme ytelsesniv\xe5 f\xf8r Llama ble lansert. Lekkasjen av Llama har vist seg \xe5 v\xe6re en av de st\xf8rste gnistene til innovasjon i LLM-omr\xe5det med \xe5pen kildekode, der en krig mellom \xe5pen kildekode og API-basert distribusjon er under oppseiling. LLama-effekten har bevist at \xe5pen kildekode er en levedyktig distribusjonsmekanisme for grunnleggende modeller, og det er noen interessante kilder til innovasjon i LLM-omr\xe5det.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35504428",children:"Discussion Service"}),'.\n"The LLama Effect"-lekkasjen har utl\xf8st alternativer med \xe5pen kildekode til ChatGPT, og f\xe5tt oppmerksomhet fra teknologieksperter. GPT-4 demonstrerer mer betydelig intelligens, og tilbyr resonnement og generaliseringsevner fra forgjengeren, GPT-3. Kun tekstbaserte AI-modeller forst\xe5r romlige resonnementer og kan forst\xe5 g\xe5ter, men manuell finjustering er n\xf8dvendig. Det er debatt rundt spr\xe5kmodellenes faktiske l\xe6ringsniv\xe5, med h\xe5p om en tilgjengelig og demokratisert AI-fremtid. LLaMA-lekkasjen har f\xf8rt til optimalisering med \xe5pen kildekode p\xe5 alle plattformer, men eksperter kritiserer piratkopiering av programvare og AI-selskapenes regulering. OpenAI kan m\xf8te juridiske utfordringer for bruk av modeller for \xe5 trene kommersielle resultater. N\xf8yaktigheten til ChatGPT varierer, og noen mener den er ubrukelig, mens andre hevder at GPT-4 er bedre p\xe5 noen omr\xe5der. Bing/Sydney og ChatGPT har forskjellige personligheter. Innlegget gir ikke nye teknologiske fakta, men diskuterer arten av tekstkomprimering.']}),"\n",(0,i.jsx)(r.h2,{id:"fra-dyp-til-lang-l\xe6ring",children:"Fra dyp til lang l\xe6ring?"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://hazyresearch.stanford.edu/blog/2023-03-27-long-learning",children:"Original"}),".\nStanford-forskere fra Hazy Research lab forbedrer sekvenslengden i grunnlagsmodeller for maskinl\xe6ring, med fokus p\xe5 \xe5 lage nesten line\xe6re tidsmodeller i sekvenslengde som kan f\xf8re til kontekstlengder p\xe5 millioner eller til og med milliarder. Hyena-modellen har skalerbarhet i sekvenslengde opp til 2k ved hjelp av et lite nevralt nettverk som parametriserer konvolusjonsfiltrene implisitt via et annet lite nevralt nettverk med en implementeringstid p\xe5 O(NlogN). Forskere utforsker l\xe6ringsmatriser og deres tilknytning til spr\xe5kapplikasjoner. N/A."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35502187",children:"Discussion Service"}),".\nStanford-forskere utforsker kostnadsreduksjon for selvoppmerksomhet i lange sekvenser. Optimalisering av beregning for GPU-er og co-prosessorer kan optimalisere LLM-er. Skepsis rundt modeller med lengre kontekst, kobling av LLM-er med andre systemer kan skape nye l\xf8sninger. GPT-4-utgivelsen f\xf8rer til ny forskning p\xe5 prediksjon av neste token, potensielle gjennombrudd i assosiativt langtidsminne. \xc5 forst\xe5 K,Q,V-representasjon er avgj\xf8rende mens RNN-er og transformatorer har implikasjoner for \xe5 demokratisere AI. Lengre kontekstlengder kan betraktes som en ny form for s\xf8k."]}),"\n",(0,i.jsx)(r.h2,{id:"ey-blir-utestengt-fra-ny-revisjonsvirksomhet-i-tyskland",children:"EY blir utestengt fra ny revisjonsvirksomhet i Tyskland."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.economist.com/business/2023/04/05/ey-gets-banned-from-new-audit-business-in-germany",children:"Original"}),".\nEY har f\xe5tt forbud mot \xe5 revidere nye b\xf8rsnoterte kunder i Tyskland i to \xe5r, etter at APAS, Tysklands regnskapstilsyn, utstedte en bot p\xe5 500 000 euro sammen med den strengeste straffen noensinne. Avgj\xf8relsen, som kommer etter en tre \xe5r lang etterforskning av EYs rolle i Wirecard-skandalen, har p\xe5f\xf8rt den kriserammede revisorgiganten et betydelig \xf8konomisk og omd\xf8mmemessig tilbakeslag. EY hadde gitt Wirecard en friskmelding inntil selskapet kollapset i 2020 etter p\xe5stander om omfattende \xf8konomisk svindel. Etter Wirecard-skandalen har EY angivelig brukt opptil 2 milliarder dollar over tre \xe5r p\xe5 \xe5 forbedre revisjonene knyttet til teknologi og oppdagelse av svindel, men ingen revisorer vil sannsynligvis gj\xf8re ting riktig hver gang."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35501937",children:"Discussion Service"}),'.\nErnst & Young (EY) har f\xe5tt forbud mot \xe5 utf\xf8re nye revisjoner i Tyskland p\xe5 grunn av feilaktige revisjonsbeslutninger og involvering i Wirecard-skandalen. Konsulentfirmaer bruker underleverand\xf8rer med lavere l\xf8nn for \xe5 minimere risikoen, men dette kan sl\xe5 tilbake. Revisorer gir bare rimelig sikkerhet og garanterer ikke at svindel ikke vil forekomme. Bruk av automatisering og kunstig intelligens kan bidra til \xe5 oppdage uredelig aktivitet. Revisjon b\xf8r skilles fra r\xe5dgivning for \xe5 unng\xe5 interessekonflikter. Det er debatt om verdien av konsulentfirmaer og behovet for "skin in the game".']}),"\n",(0,i.jsx)(r.h2,{id:"solnedgang-p\xe5-sydpolen",children:"Solnedgang p\xe5 Sydpolen"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://brr.fyi/posts/sunset",children:"Original"}),'.\nP\xe5 Sydpolstasjonen roterer solen i en nesten perfekt sirkel mot klokken rundt himmelen, og gj\xf8r ingen forskjell mellom "natt" og "dag". Som et resultat er solnedgangen spredt over flere uker, og temperaturen synker raskt n\xe5r solen st\xe5r lavt p\xe5 himmelen, vanligvis rundt midten av februar. Innlegget inneholder fotografier av solnedganger fra forskjellige retninger samt en video for \xe5 demonstrere det merkelige fenomenet. Stasjonen observerer ogs\xe5 "sommertid", selv om det ikke er noen synlig forskjell mellom tidene p\xe5 en gitt dag. Innlegget beskriver at South Pole Station f\xf8lger New Zealand-tid og gir andre data som skumringsstadier og sesongens f\xf8rste stjerneobservasjon.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35500966",children:"Discussion Service"}),".\nEt Hacker News-innlegg viser vakre bilder av solnedgang f\xf8r en 6-m\xe5neders polarnatt. Kommentarer diskuterer h\xe5ndtering av mangel p\xe5 sollys, regulering av lys og bygging av vitenskapelige anlegg. Solargrafi-eksperimentet mislyktes. Anleggskonstruksjonen p\xe5 Sydpolen er imponerende. Diskusjon om det bisarre fenomenet med solens sirkul\xe6re bevegelse og dens innvirkning p\xe5 levek\xe5rene. Antarktis er ugjestmildt og man m\xe5 konkurrere om en posisjon for \xe5 se solens oppgang og nedgang. Kommentatorene diskuterer ogs\xe5 utfordringene med \xe5 puste i ekstrem kulde. Artikkelen gir et interessant perspektiv p\xe5 livet og forskningen i Antarktis."]}),"\n",(0,i.jsx)(r.h2,{id:"en-nederlandsk-journalist-som-skriver-kritisk-om-kina-som-m\xe5l-for-skremselspropaganda",children:"En nederlandsk journalist som skriver kritisk om Kina som m\xe5l for skremselspropaganda."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://nltimes.nl/2023/04/08/dutch-journalist-writes-critically-china-targeted-bizarre-intimidation-scheme",children:"Original"}),".\nMarije Vlaskamp, en nederlandsk journalist som er kritisk til Kina, har v\xe6rt utsatt for en bisarr skremselsaksjon siden i fjor h\xf8st, som inkluderte bombetrusler og meldinger med krav om at hun skulle trekke tilbake en artikkel. Vlaskamp har tidligere skrevet kritisk om den kinesiske staten, med fokus p\xe5 undertrykkelsen av uigurene og kinesiske dissidenter i Nederland. Den kinesiske ambassaden i Haag har blitt utsatt for en bombetrussel som nevnte b\xe5de Vlaskamp og Wang Jingyu, en av personene i artiklene hennes. Mens Vlaskamps angripere ikke fors\xf8ker \xe5 skjule trusselens kinesiske opprinnelse, har den kinesiske ambassaden benektet \xe5 ha v\xe6rt involvert i \xe5 oppmuntre angriperne."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35501969",children:"Discussion Service"}),'.\nEn nederlandsk journalist utsatt for trusler; Discussion Service-brukere diskuterer kinesisk innblanding og oppfordrer myndighetene til \xe5 gj\xf8re mer. Kinesiske politistasjoner opererer i Nederland og andre land, og landene m\xe5 kanskje selv etterforske s\xe5kalte "gr\xe5 handlinger". Kritikere hevder at Kinas handlinger krenker suvereniteten, og noen politikere har blitt truet som f\xf8lge av dette. Discussion Service-brukere diskuterer Kinas rolle i nylige bombetrusler mot regimekritiske journalister bosatt i USA; debatter om Kinas regjering og dens handlinger overfor vestlige journalister. ASML, et nederlandsk selskap, dukker opp i en sammenheng der Kina har som m\xe5l \xe5 eie elektronikk i Vesten.']}),"\n",(0,i.jsx)(r.h2,{id:"usps-anlegg-i-utah-gj\xf8r-ikke-annet-enn-\xe5-tyde-h\xe5ndskrift",children:"USPS' anlegg i Utah gj\xf8r ikke annet enn \xe5 tyde h\xe5ndskrift."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://kutv.com/news/eye-on-utah/what-happens-to-mail-with-band-handwriting-united-states-postal-service-letter-carrier-usps-mailwoman-mailman-cursive-taught-in-schools-unreadable-print-envelopes-undeliverable-packages-salt-lake-city-utah",children:"Original"}),".\nUSPS-anlegget i Utah spesialiserer seg p\xe5 \xe5 tyde rotete h\xe5ndskrift p\xe5 post. Dette anlegget sysselsetter over 90 personer som sorterer posten og bruker avansert teknologi for \xe5 behandle den. Teknologien som brukes, kan til og med skanne og digitalisere h\xe5ndskrevne adresser. Anlegget viser hvordan teknologien utvikler seg for \xe5 h\xe5ndtere tradisjonelle oppgaver p\xe5 innovative m\xe5ter."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35499641",children:"Discussion Service"}),".\nUSPS-anlegget i Utah spesialiserer seg p\xe5 \xe5 tyde kursiv h\xe5ndskrift med en programvare levert av Eagle og Siemens. H\xe5ndskriftgjenkjenning har v\xe6rt en utfordring for postarbeidere, og menneskelig inngripen er fortsatt n\xf8dvendig. Diskusjonen p\xe5 Hacker News ber\xf8rer utviklingen av arbeidskraft og l\xf8nn, eiendomsbesittelse, offentlige subsidier og fordelene ved \xe5 skrive i b\xf8ker. Salt Lake Citys mormonersamfunn antas \xe5 ha bidratt til anleggets store antall dyktige lesere. Noen foresl\xe5r at USPS b\xf8r lage en mobilapp, mens andre uttrykker bekymring for brudd p\xe5 personvernet ved bruk av private data."]}),"\n",(0,i.jsx)(r.h2,{id:"apple-fortsetter-innsatsen-for-\xe5-hindre-at-butikker-fagorganiserer-seg",children:"Apple fortsetter innsatsen for \xe5 hindre at butikker fagorganiserer seg."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.bloomberg.com/news/newsletters/2023-04-09/apple-aapl-continues-efforts-to-keep-retail-stores-from-unionizing-lg9gjdx2",children:"Original"}),".\nApple pr\xf8ver \xe5 forhindre at butikkene organiserer seg, samtidig som de diversifiserer sin produkt- og komponentproduksjon utenfor Kina. Selskapet har nylig opplevd jobbkutt og en annen lederavgang. Artikkelen nevner ogs\xe5 den kommende utgivelsen av Apples headset for blandet virkelighet."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35503210",children:"Discussion Service"}),".\nApple anklaget for fagforeningsfiendtlig taktikk, inkludert tilbakeholdelse av goder; kritikk av fagforeningens forhandlingstaktikk. Diskusjon om kompleksiteten ved fagorganisering og arbeidstakerinnflytelse. Gallup-unders\xf8kelse viser \xf8kende interesse for fagorganisering, s\xe6rlig blant frontlinjearbeidere. Noen kritiserer den lave l\xf8nnen og mangelen p\xe5 goder i detaljhandelen, mens andre hevder at ansiennitetsbaserte forfremmelser og oppsigelser kan p\xe5virke selskapene negativt."]}),"\n",(0,i.jsx)(r.h2,{id:"plrust-10-n\xe5-et-p\xe5litelig-spr\xe5k-for-postgres",children:"PL/Rust 1.0: n\xe5 et p\xe5litelig spr\xe5k for Postgres"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://tcdi.github.io/plrust/plrust.html",children:"Original"}),'.\nPL / Rust er et lastbart prosedyrespr\xe5k som gj\xf8r det mulig \xe5 skrive PostgreSQL-funksjoner i Rust, og gir tilgang til Postgres \'Server Programming Interface og sikre Rust-typer over de fleste Postgres-innbygde datatyper; PL / Rust-funksjoner kompileres til innf\xf8dt maskinkode i stedet for \xe5 bli tolket, noe som gir best ytelse. PL / Rust er n\xe5 et p\xe5litelig prosedyrespr\xe5k for Postgres p\xe5 x86_64 og aarch64-systemer hvis riktige kompileringskrav er oppfylt, slik at PL / Rust kan leve i et univers av Safe Rust; PL / Rust bruker sin egen rustc-driver for \xe5 bruke tilpassede lints til en brukers LANGUAGE plrust-funksjon for \xe5 bruke visse kodeuttrykk som de vet ikke har "I-Unsound" -problemer. Som standard vil ikke PL/Rust utf\xf8re krysskompilering, men det m\xe5 installeres og aktiveres gjennom konfigurasjon.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35501065",children:"Discussion Service"}),".\nPL/Rust 1.0 stoler n\xe5 p\xe5 Postgres som et alternativ for databasefunksjoner. Skyleverand\xf8rene RDS og Supabase muliggj\xf8r implementering av PL/Rust. Har eksepsjonell ytelse, men fortsatt s\xe5rbar for problemer. Hendelsesutl\xf8sere og DO-blokker er ikke innlemmet enn\xe5. Rust har tilgang til utviklings\xf8kosystem, effektive typer og bedre ytelse. Kan begrense optimalisering for beregningsutl\xf8sere."]}),"\n",(0,i.jsx)(r.h2,{id:"twitter-blokkerer-likes-og-retweets-som-nevner-substack",children:"Twitter blokkerer likes og retweets som nevner Substack."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://flipboard.social/@Flipboard/110161362001035875",children:"Original"}),".\nN/A."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35502684",children:"Discussion Service"}),".\nTwitter blokkerer likes/retweets som nevner Substack, for\xe5rsaker Streisand-effekt. Elon Musk beskylder Substack for \xe5 skrape Twitter-databasen, eksperter finner uttalelsen meningsl\xf8s. Substack benekter utilb\xf8rlig bruk av Twitter API-er. Kritikk av Twitters s\xf8keresultater, forbud og retningslinjer for API-bruk. Bekymringer over kvaliteten p\xe5 Substacks nyhetsfeed-funksjon. Konkurrerende Twitter og Substack utvikler seg, alternative mikrobloggingsprotokoller utforskes. Motstand mot \xe5 gj\xf8re saken til et skuespill, krav om ansvarliggj\xf8ring av ledelsen. Debatter p\xe5g\xe5r om API-misbruk og Substacks p\xe5st\xe5tte skraping av Twitter-innhold. Advarsel mot \xe5 avfeie situasjonen til oppsagte Substack-ansatte."]}),"\n",(0,i.jsx)(r.h2,{id:"z-library-skal-la-brukerne-dele-fysiske-b\xf8ker",children:"Z-Library skal la brukerne dele fysiske b\xf8ker."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://torrentfreak.com/z-library-plans-to-let-users-share-physical-books-through-z-points-230408/",children:"Original"}),'.\nZ-Library, det st\xf8rste depotet for piratkopierte b\xf8ker, utvider tjenestene sine til \xe5 omfatte et fysisk bokdelingsmarked, med millioner av brukere som kan hente pocketb\xf8ker p\xe5 egne "Z-Points" rundt om i verden. Den planlegger \xe5 organisere "innsamlings- og lagringspunkter" for b\xf8ker som "vil v\xe6re bindeleddet mellom de som deler b\xf8kene sine og de som trenger dem", noe som vil kreve betydelig lagringsplass og organisatorisk innsats, s\xe5 oppfyllingssentre og tredjepartslogistikktjenester er velkomne. En kunngj\xf8ring lagt ut p\xe5 nettstedet ser ut til \xe5 v\xe6re seri\xf8s, med folk som foresl\xe5r Vietnam, Brasil, Portugal, Colombia, Iran, Usbekistan, Nigeria, Spania, India, Argentina, Egypt, Frankrike, Etiopia, Kina og Ghana som ideelle Z-Point-steder, og nettstedet tar for tiden imot tilbakemeldinger for \xe5 forbedre tjenesten.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35499065",children:"Discussion Service"}),".\nZ-Library vil tillate brukere \xe5 dele fysiske b\xf8ker, men utgivere kan saks\xf8ke biblioteket; noen foresl\xe5r \xe5 skanne b\xf8ker, endre opphavsrettslover eller oppmuntre til skanning av b\xf8ker. Noen diskuterer gjennomf\xf8rbarheten og konsekvensene for forlagene av \xe5 lansere et reelt bokdelingsmarked. Lisensmodeller for e-b\xf8ker har uheldige konsekvenser og f\xf8rer til piratkopiering som en form for protest. Private medlemsbibliotek er eldre enn offentlige bibliotek og l\xe5ner ofte ut b\xf8ker."]}),"\n",(0,i.jsx)(r.h2,{id:"perseus---nextjs-alternativ-i-rust",children:"Perseus - NextJS alternativ i Rust"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://framesurge.sh/perseus/en-US/",children:"Original"}),".\nPerseus er et Rust-rammeverk for moderne webapper som genererer tilstand p\xe5 foresp\xf8rsel og sender den til Sycamore, med Fluent-basert I18n lagt til for flerspr\xe5klig funksjonalitet, plugins for tilpasning, alt i WebAssembly for h\xf8y ytelse, og eksporterbar/statisk servert, enkel \xe5 installere og brukervennlig."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35500528",children:"Discussion Service"}),".\nBrukere diskuterer Perseus, et Rust-basert alternativ til NextJS, og noen foretrekker JS for frontend-utvikling p\xe5 grunn av Rusts verkt\xf8y. Til tross for dette tyder Rusts inntog i de lavere niv\xe5ene av JS-stakken p\xe5 at det er potensial for \xe5 innlemme JS/TS i Rust-rammeverk som Perseus. Det oppst\xe5r diskusjon rundt Rusts fordeler sammenlignet med Go, der noen brukere ser Rust som mer egnet for programmering p\xe5 lavt niv\xe5, mens andre ser Go som bedre egnet for webutvikling. Verdien av et programmeringsspr\xe5k avhenger av hvor man bor og \xf8nsker \xe5 jobbe. Utgivelsen av Perseus fanger oppmerksomheten til teknologikyndige personer som et mulig raskere alternativ til Svelte, men m\xf8ter kritikk for \xe5 v\xe6re vanskelig for bruk i den virkelige verden."]}),"\n",(0,i.jsx)(r.h2,{id:"en-baby-gpt",children:"En baby-GPT"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://twitter.com/karpathy/status/1645115622517542913",children:"Original"}),".\nN/A."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35506069",children:"Discussion Service"}),".\nEn Discussion Service-bruker foresl\xe5r \xe5 bruke bin\xe6re regul\xe6re uttrykk for spr\xe5krelasjoner, mens en annen argumenterer for mening og hensikt. Skaper av baby GPT sammenligner med Markov-kjede. Ekspert anbefaler bedre matematiske verkt\xf8y. Discussion Service-bruker sp\xf8r om implikasjoner for allmennheten. Ingen bemerkelsesverdig ny teknologi eller utgivelse."]}),"\n",(0,i.jsx)(r.h2,{id:"to-typer-programvareingeni\xf8rer",children:"To typer programvareingeni\xf8rer"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://registerspill.thorstenball.com/p/two-types-of-software-engineers",children:"Original"}),".\nArtikkelen diskuterer to typer programvareingeni\xf8rer: Type 1, som antar at et problem er enkelt hvis det ikke er teknisk, og type 2, som antar at det er vanskelig fordi det involverer mennesker. Type 1 tror p\xe5 Engineering med stor E, mens type 2 fokuserer p\xe5 mennesker og ser p\xe5 tekniske problemer som noe som involverer mennesker. Mens type 1 er mer vanlig, forst\xe5r type 2-ingeni\xf8rer at prosjektering inneb\xe6rer kaos og kompleksitet, og har som m\xe5l \xe5 bygge til tross for disse utfordringene. Artikkelen inneholder noen eksempler for \xe5 illustrere forskjellene, men forfatteren har enn\xe5 ikke definert eller trukket grensen mellom de to typene n\xf8yaktig."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35503784",children:"Discussion Service"}),".\nEn diskusjon om to typer programvareingeni\xf8rer, inkludert type 3, og viktigheten av \xe5 forst\xe5 produktstyring. Debatt om \xe5 balansere innovasjon og stabilitet, og behovet for riktig dokumentasjon. Motsetningen mellom \xe5 stole p\xe5 mennesker og \xe5 implementere automatiserte l\xf8sninger i programvareutvikling. Viktigheten av \xe5 samordne alle om felles m\xe5l og forst\xe5 st\xf8rre forretningsbehov. Kategorisering av programvareingeni\xf8rer avh\xf8rt, med vekt p\xe5 \xe5 finne \xe5rsaken til problemer. Innlegget fungerer som stoff til ettertanke."]}),"\n",(0,i.jsx)(r.h2,{id:"avansert-linux-programmering-2001",children:"Avansert Linux-programmering (2001)"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://mentorembedded.github.io/advancedlinuxprogramming/",children:"Original"}),".\n'Advanced Linux Programming' av CodeSourceryLLC er en bok som hjelper GNU/Linux-utviklere med \xe5 lage programvare med brukervennlige funksjoner, avanserte funksjoner som multi-threading, interprosess-kommunikasjon og interaksjon mellom maskinvareenheter og generell programforbedring. I tillegg l\xe6rer denne boken utviklere hvordan de skal arbeide i GNU/Linux-milj\xf8et, inkludert dets unike begrensninger, konvensjoner og muligheter. Denne boken er tilgjengelig for nedlasting under Open Publication License, versjon 1, og kommer med tilgang til dekket GNU General Public License-kodeeksempler. Errata og oversettelser av boken er tilgjengelig."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35500197",children:"Discussion Service"}),'.\nHacker News-brukere diskuterer relevansen av boken "Advanced Linux Programming" fra 2001 i 2021. Noen brukere foresl\xe5r \xe5 oppdatere utdaterte seksjoner. Til tross for at det er en nybegynnerbok, er den fortsatt en nyttig ressurs for Linux API-utvikling. Aria2 nedlastingsapplikasjon fungerer som et alternativ til serverhastighetsbegrensninger.']}),"\n",(0,i.jsx)(r.h2,{id:"et-cern-for-\xe5pen-kildekode-for-storskala-ai",children:"Et CERN for \xe5pen kildekode for storskala AI"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.openpetition.eu/petition/online/securing-our-digital-future-a-cern-for-open-source-large-scale-ai-research-and-its-safety",children:"Original"}),".\nLAION e.V. har lansert en underskriftskampanje for et internasjonalt, offentlig finansiert forskningsanlegg for superdatabehandling med \xe5pen kildekode for KI, tilsvarende CERN, for \xe5 demokratisere KI-forskning og fremme sikkerhetsforskning. Plattformen openPetition har som m\xe5l \xe5 styrke borgernes deltakelse og st\xf8tte underskriftskampanjer for endring. Initiativet tar sikte p\xe5 \xe5 beskytte demokratiske prinsipper mot \xe5 bli undergravd av noen f\xe5 store selskaper. En Discussion Service-bruker bemerket at 19 % av st\xf8ttespillerne kommer fra laion.ai, mens 64 % er ukjente. Innbyggerne oppfordres til \xe5 donere for \xe5 st\xf8tte underskriftskampanjen som har f\xe5tt gjennomslag p\xe5 Hacker News."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35501845",children:"Discussion Service"}),".\nEn artikkel p\xe5 openpetition.eu fremhever Europas behov for et CERN-lignende \xe5pen kildekode-initiativ for \xe5 fremme samarbeid mellom KI-forskere, akademikere og gr\xfcndere. Samarbeid er n\xf8dvendig for \xe5 utf\xf8re stordatabehandling med store kapitalinvesteringer. \xc5pen kildekode-prosjekter er n\xf8dvendige for \xe5 holde p\xe5 KI-forskere og gagne samfunnet i stedet for bedriftsaksjon\xe6rer. CERNs suksess gj\xf8r det til en attraktiv modell, selv om noen mener at markedet gir tilstrekkelige insentiver. Den tverrfaglige karakteren til kunstig intelligens krever at man tar hensyn til sammenhengende problemstillinger."]}),"\n",(0,i.jsx)(r.h2,{id:"permafrost-motoren---en-opengl-rts-spillmotor-skrevet-i-c",children:"Permafrost-motoren - en OpenGL RTS-spillmotor skrevet i C."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://github.com/eduard-permyakov/permafrost-engine",children:"Original"}),".\nPermafrost Engine er en OpenGL 3.3 Real Time Strategy-spillmotor skrevet i C, laget i bildet av gamle klassikere, men inneholder noen moderne ideer. EVERGLORY er flaggskipspillet utviklet ved hjelp av Permafrost Engine, med motorens evner med f\xf8rsteh\xe5nds spillopplevelse. Motorsammendraget inneholder en liste over OpenGL- og Python-funksjoner, RTS-mekanikk og plattformfunksjoner. Lisensen for Permafrost Engine er GPLv3, med et spesielt koblingsunntak. Byggeinstruksjoner er gitt for b\xe5de Linux og Windows. En devlog og e-post for sp\xf8rsm\xe5l/kommentarer ang\xe5ende prosjektet eller kildekoden er tilgjengelig for interesserte brukere."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35504053",children:"Discussion Service"}),".\nPermafrost-motoren med \xe5pen kildekode f\xe5r oppmerksomhet p\xe5 Discussion Service for et nytt RTS-spill med \xe5pen kildekode. Everglory-spillets skrifttydelighet kritiseres. Sammenligning med andre RTS-motorer etterlyses. Utviklernes testing p\xe5 h\xe5ndholdte skjermer er viktig. H\xe5per p\xe5 RTS-sjangerens gjenoppliving. Brukere diskuterer RTS-motorer med \xe5pen kildekode og spr\xe5k som brukes. En annen \xe5pen kildekode-implementering av Frostbite-motoren nevnes."]}),"\n",(0,i.jsx)(r.h2,{id:"lukke-en-foreldet-ssh-tilkobling",children:"Lukke en foreldet SSH-tilkobling."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://davidisaksson.dev/posts/closing-stale-ssh-connections/",children:"Original"}),".\nInnlegget diskuterer hvordan du lukker en foreldet SSH-\xf8kt, og sier at mens den f\xf8rste l\xf8sningen kan v\xe6re \xe5 lukke terminalemulatoren, er det en bedre m\xe5te \xe5 bruke innebygde SSH-escape-sekvenser. Innlegget forklarer hvordan prefikset tilde (",(0,i.jsx)(r.del,{children:") etterfulgt av en kommando kan utl\xf8se flere skjulte kommandoer i SSH-klienter, inkludert kommandoen 'terminate session' ("}),'.). Innlegget bemerker at det b\xf8r tas hensyn til det faktum at en foreg\xe5ende ny linje er n\xf8dvendig, og gir et lite notat for personer som bruker et tastatur med nordisk layout for \xe5 skrive tilde-tegnet. Innlegget avsluttes med en diskusjon om hva som skal gj\xf8res etter bruk av escape-sekvensen "terminate session".']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35504402",children:"Discussion Service"}),".\nEn Discussion Service-bruker gir et SSH-tips. En annen p\xe5peker et layoutproblem, men gir en l\xf8sning. Det foresl\xe5s \xe5 konfigurere EscapeChar. Diskusjon om SSH-manpage, hoppende verter og SSH-tilkoblinger. Sticky SSH-\xf8kt er \xf8nsket. Autossh anbefales for automatisk tilkobling, og Mosh for \xe5 endre portvideresending. Krypteringsdetaljer og ytterligere tips gitt. Advarsel mot \xe5 bruke Alpine Linux."]}),"\n",(0,i.jsx)(r.h2,{id:"flatcar-container-linux",children:"Flatcar Container Linux"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.flatcar.org/",children:"Original"}),".\nFlatcar Container Linux er en felles Linux-distribusjon som er designet for container-arbeidsbelastninger med h\xf8y sikkerhet og lite vedlikehold. OS-bildet inkluderer bare verkt\xf8yene som kreves for \xe5 kj\xf8re containere uten pakkebehandling eller konfigurasjonsdrift. Det uforanderlige filsystemet og automatiserte atomoppdateringer gir et sterkt grunnlag for infrastruktursikkerhet. Flatcar Container Linux sine innebygde sikkerhetsfunksjoner og reduserte angrepsflate forenkler administrasjonen av operativsystemet. Det inkluderer verkt\xf8y for \xe5 administrere store infrastrukturer og st\xf8tter globale initiativer. Automatiserte, atomiske oppdateringer sikrer at du kj\xf8rer den mest stabile, sikre og oppdaterte Flatcar-versjonen. Det er en drop-in erstatning for CoreOS Container Linux."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35503928",children:"Discussion Service"}),".\nMicrosofts Flatcar Container Linux-oppdatering og fortsetter etter oppkj\xf8pet, og gir et alternativ til CloudInit. Den uforanderlige infrastrukturtiln\xe6rmingen blir stadig mer popul\xe6r til tross for Ignitions tekniske problemer. Flatcar Linux-utviklere foresl\xe5r en vennlig oppdatering. Discussion Service-brukere diskuterer \xe5 legge til containere og foresl\xe5r en UEFI-firmware for bedre ytelse."]}),"\n",(0,i.jsx)(r.h2,{id:"microsoft--jarvis-et-system-for-\xe5-koble-llm-er-med-ml-fellesskapet",children:"Microsoft / JARVIS: et system for \xe5 koble LLM-er med ML-fellesskapet"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://github.com/microsoft/JARVIS",children:"Original"}),".\nMicrosoft og Hugging Face har avduket Labs-prosjektet JARVIS, en AI-assistent for \xe5 koble spr\xe5k- og maskinl\xe6ringsmodeller. JARVIS bruker en stor spr\xe5kmodell (LLM) for \xe5 forst\xe5 og analysere foresp\xf8rsler, og bruker deretter et utvalg av mange ekspertmodeller for \xe5 utf\xf8re den n\xf8dvendige oppgaven. Den best\xe5r av fire trinn: oppgaveplanlegging, modellvalg, oppgaveutf\xf8relse og generering av svar. Brukeren kan nyte en lett opplevelse med JARVIS uten \xe5 distribuere modellene lokalt ved \xe5 aktivere CLI-modus eller nettsiden, som viser et brukervennlig grensesnitt som kommuniserer med JARVIS."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35500472",children:"Discussion Service"}),".\nMicrosoft lanserer JARVIS for \xe5 koble LLM-er med ML-samfunnet ved hjelp av regelbaserte tiln\xe6rminger og maskinl\xe6ring. Noen spekulerer i om autonome AI-agenter kan beg\xe5 svindel eller svindel, selv om leserne hovedsakelig er begeistret. Jarvis genererer tekst og bilder basert p\xe5 LLMs valg av modeller, men noen uttrykker bekymring for varemerkesp\xf8rsm\xe5l og avlytting."]}),"\n",(0,i.jsx)(r.h2,{id:"sf\xe6risk-tokamak-oppn\xe5r-avgj\xf8rende-plasmatemperaturer",children:"Sf\xe6risk tokamak oppn\xe5r avgj\xf8rende plasmatemperaturer"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.eetimes.com/spherical-tokamak-achieves-crucial-plasma-temperatures/",children:"Original"}),".\nTokamak Energys sf\xe6riske tokamak oppn\xe5dde ionetemperaturer p\xe5 over 100 millioner grader Kelvin - et kritisk skritt i utviklingen av fusjonsenergiteknologi. Den lille st\xf8rrelsen, plasmastabiliteten og de magnetiske inneslutningsegenskapene til sf\xe6riske tokamakker gj\xf8r dem til et attraktivt valg for kommersiell fusjonskraftproduksjon. Steven McNamara, vitenskapsdirekt\xf8r i Tokamak Energy, mener at selskapet kan ta fusjonsenergi i bruk innen 10 \xe5r, som et supplement til andre fornybare energikilder. Gjennombruddet bruker Thomson-spredning til \xe5 m\xe5le temperatur og tetthet p\xe5 flere punkter, noe som baner vei for rimelige, utplasserbare kommersielle fusjonskraftverk. Teknologien har ogs\xe5 potensielle anvendelser innen b\xe6rekraftig luftfart og produksjon av hydrogenbrensel."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35505342",children:"Discussion Service"}),".\nEn sf\xe6risk tokamak oppn\xe5r kritiske plasmatemperaturer. Noen brukere diskuterer strukturelle sp\xf8rsm\xe5l, en anbefaler en podcast om fusjonsenergi. Artikkelen forklarer behovet for en varmeveksler og reduserte kostnader ved den nye konstruksjonen. Levedyktigheten til kommersiell fusjon diskuteres. Fordobling av magnetstyrken i sm\xe5skala tester gir fremskritt. Avfalls- og sikkerhetsfordelene ved fusjon i forhold til fisjon nevnes. Sf\xe6riske tokamakker er en toppmoderne anvendelse. Milep\xe6len som er n\xe5dd, er enn\xe5 ikke nyttig, men det gj\xf8res fremskritt n\xe5r det gjelder magnetstyrke."]}),"\n",(0,i.jsx)(r.h2,{id:"de-f\xf8rste-p\xe5skeeggene-var-et-oppr\xf8r-fra-bedriftens-side",children:'De f\xf8rste "p\xe5skeeggene" var et oppr\xf8r fra bedriftens side.'}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://thehustle.co/the-first-easter-eggs-were-an-act-of-corporate-rebellion/",children:"Original"}),'.\nDe f\xf8rste p\xe5skeeggene i videospill var et resultat av at designere ble nektet \xe6ren for arbeidet sitt, noe som f\xf8rte til skjulte budskap i spillene. Det f\xf8rste p\xe5skeegget ble funnet i Ataris spill "Adventure" fra 1980, laget av Warren Robinett. Tradisjonen med skjulte budskap fortsatte i 1970-tallets arkadespill for \xe5 oppn\xe5 anerkjennelse og individualitet. Robinetts p\xe5skeegg hevet statusen hans, og han utviklet en vellykket programvarevirksomhet. The Tech Times rapporterer om ulike informasjonskapsler som brukes av selskaper for \xe5 spore brukernes atferd p\xe5 nettet og tilpasse annonser, men de er ikke klassifisert enn\xe5.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35503260",children:"Discussion Service"}),".\nEt innlegg i Hacker News om bedriftsoppr\xf8r gjennom p\xe5skeegg inneholder anekdoter og aktuelle bedriftspolicyer. Lesernes interesse kan vekkes p\xe5 grunn av den historiske relevansen og utviklingen av p\xe5skeeggets rolle. Dagens p\xe5skeegg uttrykker bedriftsstolthet, ikke ulydighet. Kodegjennomganger forhindrer p\xe5skeegg. Tidligere teknologiselskaper faller ofte under nyutnevnte MBA-er. Warren Robinett f\xe5r skryt for Adventure game. U2s medlem og Atari-fan har forskjellige navn."]}),"\n",(0,i.jsx)(r.h2,{id:"modul\xe6re-feil-i-rust",children:"Modul\xe6re feil i Rust"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://sabrinajewson.org/blog/errors",children:"Original"}),".\nArtikkelen diskuterer viktigheten av modul\xe6r feilh\xe5ndtering og introduserer prinsippet om at feiltyper skal v\xe6re i n\xe6rheten av sin feilenhet, ved \xe5 bruke et hypotetisk Rust-bibliotek som eksempel. Problemer med unyttige feilmeldinger, manglende utvidbarhet og vanskeligheter med \xe5 matche feil skisseres, og l\xf8sninger som .source()-metoden og bedre konstruksjon av feiltyper foresl\xe5s. Eksempelbibliotekets feiltype er delt inn i tre forskjellige typer med god tilbakesporing og presis feilmatching, og I/O-feil forklares gjennom en mer strukturert feiltypekonstruksjon. Artikkelen understreker betydningen av gode backtraces, utvidbarhet, inspiserbarhet, stabilitet og modularitet i feilh\xe5ndtering, og antyder at god feilh\xe5ndtering er verdt \xe5 l\xe6re."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35502874",children:"Discussion Service"}),".\nRusts feilmeldinger er popul\xe6re, men det er behov for varierte feiltyper. SNAFU gj\xf8r det mulig \xe5 produsere unike spor. Tydelige feil reduserer spredning og gj\xf8r h\xe5ndteringen enklere, men v\xe6r forsiktig med \xe5 st\xf8tte offentlige API-er. Logging og terminering b\xf8r ikke v\xe6re den prim\xe6re tiln\xe6rmingen for feils\xf8king av biblioteker. Granul\xe6re eller ugjennomsiktige feil med beskrivelser er \xe5 foretrekke. Kontrollerte unntak i Java er \xe5 foretrekke. Den fatale feilen med Java er \xe5 ikke ha algebraiske typer."]}),"\n",(0,i.jsx)(r.h2,{id:"68-95-997-regel",children:"68-95-99.7 Regel"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://en.wikipedia.org/wiki/68%E2%80%9395%E2%80%9399.7_rule",children:"Original"}),".\n68-95-99.7-regelen er en statistisk tiln\xe6rming som estimerer prosentandelen av verdier innenfor et standardavvik fra gjennomsnittet i normalfordelingen. Regelen sier at omtrent 68 %, 95 % og 99,7 % faller innenfor henholdsvis ett, to og tre standardavvik. Denne regelen har flere bruksomr\xe5der, for eksempel kvalitetskontroll og dataanalyse. Det er en rask m\xe5te \xe5 f\xe5 et grovt sannsynlighetsestimat for en populasjon som antas \xe5 v\xe6re normal. Formelen kan brukes p\xe5 forskjellige fordelinger, og den kan bidra til \xe5 identifisere ekstremverdier i dataanalyser."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35501780",children:"Discussion Service"}),".\nDiscussion Service-kommentarer diskuterer begrensninger ved 68-95-99,7-regelen i analyse av data. Nassim Nicholas Talebs arbeid og Chebyshevs ulikhet nevnes. Tangenter p\xe5 finansiell handel og historie om det amerikanske opsjonsmarkedet. Ekspertbrukere hevder at h\xf8ye IQ-poeng er up\xe5litelige og skalaen er vilk\xe5rlig."]}),"\n",(0,i.jsx)(r.h2,{id:"unicodeplots",children:"UnicodePlots"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://github.com/JuliaPlots/UnicodePlots.jl",children:"Original"}),".\nUnicodePlots-biblioteket er et plottingsverkt\xf8y p\xe5 h\xf8yt niv\xe5 for bruk i Julias REPL som inkluderer spredningsdiagrammer, linjediagrammer og varmekart. Det st\xf8tter ogs\xe5 fysiske mengder fra Unitful.jl og intervaller fra IntervalSets.jl, tillater tilpasning av plottfunksjoner som plotth\xf8yde og -bredde og reversere / snu plottakser, og st\xf8tter lagring av plott som PNG eller TXT."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35505591",children:"Discussion Service"}),".\nJulia-baserte UnicodePlots viser diagrammer og histogrammer p\xe5 terminalen for rask visualisering p\xe5 eksterne servere. Det svarer p\xe5 et behov for rask datavisualisering i terminalen, uten \xe5 installere en full grafikkstabel. UnicodePlots er for det meste kopiert i en Ruby-port, og en Python-versjon som er kompatibel med Matplotlib. Det er for tiden en trend mot tekstbrukergrensesnitt, noe som skaper en splittelse mellom Electron for sluttbrukerapper og TUI for b\xe6rbare verkt\xf8y. Den har 100 % kodedekning, st\xf8tter komparative histogrammer og lar brukerne kopiere og lime inn data rett inn i kommentarer eller beskrivelser. Selv om det ikke er en helt ny teknologi, er UnicodePlots et nyttig verkt\xf8y for dem som trenger \xe5 vurdere data raskt."]}),"\n",(0,i.jsx)(r.h2,{id:"digitale-samleobjekter-p\xe5-instagram-er-i-ferd-med-\xe5-avvikles",children:"Digitale samleobjekter p\xe5 Instagram er i ferd med \xe5 avvikles"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://help.instagram.com/1824155514623095",children:"Original"}),".\nFra og med 11. april 2023 vil Instagram avvikle sin st\xf8tte til digitale samleobjekter, noe som p\xe5virker opprettelsen av nye digitale samleinnlegg, visningen av digitale lommeb\xf8ker og tilgjengeligheten av blockchain-informasjon. Sletting av digitale samleobjekter vil skje i samsvar med Instagrams retningslinjer for personvern og vilk\xe5r for bruk av digitale samleobjekter, men brukere kan sende inn en foresp\xf8rsel om \xe5 laste ned informasjonen sin f\xf8r fristen. Innholdet i digitale lommeb\xf8ker fra tredjeparter vil ikke bli ber\xf8rt."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35501074",children:"Discussion Service"}),'.\nInstagrams digitale samleobjekter mister fart, men web3-troende blir ikke avskrekket. NFT-rommet m\xe5 ta for seg eierskapsstandarder og forretningsadopsjon. Reddits avatarer selger godt, selv om polygon NFT-er oppfattes som mindre verdifulle. Winter er velkommen for utbyggere \xe5 bygge infrastruktur og for tradisjonelle virksomheter \xe5 l\xe6re om desentraliserte nettverk. Suksessen til Pokemon-kort og Reddit-funksjoner sammenlignes med begrepet knapphet. Uttrykket "Web3" kan v\xe6re forhastet, og svindlere og utbyggere er i forskjellige leire. Det er skepsis og bekymring for NFT-hype, investeringsrisiko og mental helse. Kultinvolvering i bransjer, krypto og AI-risiko diskuteres. ChatGPTs nytte diskuteres, og brukerne fokuserer p\xe5 ny innsikt uten politisk eller religi\xf8st spr\xe5k. Konteksten for avansert teknologi n\xe5r det gjelder kommunikasjon og jordsynkronisering diskuteres, med varierende meninger om NFT-verdien og dens innvirkning p\xe5 samfunnet.']}),"\n",(0,i.jsx)(r.h2,{id:"dommen-som-truer-bibliotekenes-fremtid-dommen-som-truer-bibliotekenes-fremtid",children:"Dommen som truer bibliotekenes fremtid Dommen som truer bibliotekenes fremtid"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.theatlantic.com/ideas/archive/2023/04/internet-archive-libraries-federal-court-ruling/673615/",children:"Original"}),'.\nEn f\xf8deral domstolsavgj\xf8relse om at kontrollert digitalt utl\xe5n (CDL) er i strid med opphavsretten, kan f\xe5 katastrofale f\xf8lger for bibliotekene, blant annet at de m\xe5 velge mellom \xe5 kj\xf8pe dyre eboklisenser fra utgivere eller utvide samlingene sine; Internet Archive (IA), en ideell organisasjon som l\xe5ner ut digitale kopier av millioner av b\xf8ker de har samlet og digitalisert, har v\xe6rt i sentrum for en rettssak fra flere bokforlag som saks\xf8kte dem i 2020 med p\xe5stand om brudd p\xe5 opphavsretten; og det var denne CDL-utl\xe5nsmodellen retten avgjorde mot forrige m\xe5ned, som kan ha "urettferdig makt over fremtiden til b\xe5de b\xf8ker og biblioteker", if\xf8lge advokat Corynne McSherry fra Electronic Frontier Foundation, som representerer IA i sin anke over kjennelsen.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35502238",children:"Discussion Service"}),".\nEn rettsavgj\xf8relse om kontrollert digitalt utl\xe5n og opphavsrettslover har utl\xf8st debatter, med forslag om \xe5 forkorte opphavsrettens lengde for \xe5 forhindre tap av kunnskap; noen antyder at utgivernes fortjeneste ikke b\xf8r v\xe6re problemet ved utl\xe5n av CDL-materiale. Bibliotekene har tilpasset seg til \xe5 bli offentlige underholdningssentre, og offentlig tilgang til ressurser er avgj\xf8rende; bibliotekarer bruker ekspertuttalelser for \xe5 balansere utl\xe5nspopularitet, bokverdi og bibliotekets oppdrag n\xe5r de kasserer b\xf8ker. Forlagss\xf8ksm\xe5l mot Internet Archives ubegrensede avgiftsfrie digitale distribusjon g\xe5r ut over forfatternes inntekter, og kontrollert digitalt utl\xe5n kan sette opphavsrettslovgivningens beskyttelse i fare. Skj\xe6ringspunktet mellom digitalt og fysisk eierskap er fortsatt gjenstand for debatt, og diskusjonene gir unike perspektiver p\xe5 den aktuelle problemstillingen."]}),"\n",(0,i.jsx)(r.h2,{id:"do-kwon-konverterte-ulovlige-midler-fra-luna-til-bitcoin",children:"Do Kwon konverterte ulovlige midler fra LUNA til Bitcoin."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://cointelegraph.com/news/do-kwon-converted-stolen-funds-from-luna-to-bitcoin-s-korean-prosecutors",children:"Original"}),".\nS\xf8rkoreanske p\xe5talemyndigheter har identifisert nesten 314,2 millioner dollar i ulovlige eiendeler knyttet til Terraform Labs 'medstifter, Do Kwon, og hans medarbeidere, hvorav Kwon alene er knyttet til rundt 69 millioner dollar. P\xe5talemyndighetene har kontaktet Binance for \xe5 stanse enhver uttaksforesp\xf8rsel knyttet til Kwon. Kwon konverterte angivelig det meste av de ulovlige midlene, som utgj\xf8r rundt 414,5 milliarder won, til Bitcoin, og ingen av eiendelene knyttet til ham kan inndrives eller er under jurisdiksjonen til s\xf8rkoreanske myndigheter. Terra var et krypto\xf8kosystem som kollapset i mai 2022, der tidligere administrerende direkt\xf8r Kwon ble beskyldt for \xe5 ha tappet Bitcoin til en verdi av nesten 100 millioner dollar etter kollapsen."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35499996",children:"Discussion Service"}),".\nOn-chain data viser Terraform Labs' Do Kwons Bitcoin-konvertering av falske LUNA-midler. Avsl\xf8rer begrensninger ved sporing av svindel gjennom tradisjonelle banker. Discussion Service-brukere diskuterer personvernverkt\xf8y og \xe6rlighet i kryptorommet. Debatt om etterretning utviklet seg for konkurranse eller samarbeid, med noen som argumenterer for sistnevnte. Konkurranse og predasjon driver konkurranse, men den generelle trenden er \xe5 fortsette \xe5 diskutere roller i etterretningsutviklingen."]}),"\n",(0,i.jsx)(r.h2,{id:"intervju-med-andrew-kelley-zig-creator-2021-engelsk",children:"Intervju med Andrew Kelley (Zig Creator) (2021) (engelsk)"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://corecursive.com/067-zig-with-andrew-kelley/",children:"Original"}),".\nAndrew Kelley diskuterer sine erfaringer med \xe5 utvikle programmeringsspr\xe5ket Zig, utfordringene med \xe5 balansere en fulltidsjobb med arbeid med \xe5pen kildekode, viktigheten av \xe5 forhandle om eierskap til intellektuell eiendom og de moralske sp\xf8rsm\xe5lene rundt kommersiell forking i \xe5pen kildekode-fellesskapet. Zig er et ikke-kommersielt programmeringsspr\xe5k som tar sikte p\xe5 \xe5 forbedre minnesikkerheten og redusere informasjonsoverbelastning for brukerne. Kelley ser for seg Zig som det foretrukne spr\xe5ket for operativsystemer og l\xe6reb\xf8ker, noe som f\xf8rer til bedre applikasjonsytelse, minnebruk og stabilitet. Tech Times rapporterer ogs\xe5 om ulike programmeringsfokuserte videokurs som er tilgjengelige p\xe5 nettet."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35502151",children:"Discussion Service"}),".\nCorecursives intervju med Zig Creator Andrew Kelley inspirerer lytterne til \xe5 laste ned alle tidligere podcaster p\xe5 nettstedet, og diskuterer folkefinansieringsprosjekter og personlige r\xe5d i separate kommentarer. En lytter setter pris p\xe5 den vennlige atmosf\xe6ren i #chicken scheme-kanalen. En annen fremhever Andrew Kelleys \xe5penhet i en hendelse med Zig, men en bruker reagerer negativt p\xe5 interaksjonen med Kelley. Samlet sett liker lytterne intervjuets dekning av Zig og SQLites teknologiske historie."]}),"\n",(0,i.jsx)(r.h2,{id:"vis-supavisor---en-postgres-tilkoblingspool-skrevet-i-elixir",children:"Vis Supavisor - en Postgres-tilkoblingspool skrevet i Elixir."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://github.com/supabase/supavisor",children:"Original"}),".\nSupavisor er en Postgres-tilkoblingspool som kan proxy millioner av Postgres-sluttklienttilkoblinger til en stateful pool av native Postgres-databasetilkoblinger via en skalerbar, cloud-native arkitektur. Dette systemet forenkler Postgres-klyngeadministrasjon for databaseadministratorer ved \xe5 tilby enkel konfigurasjon av h\xf8ytilgjengelige Postgres-klynger, samtidig som det er ressurseffektivt, skalerbart, multi-tenant og Cloud-native. Det er allerede tilgjengelige benchmarks og belastningstester som viser at det kan h\xe5ndtere en million Postgres-tilkoblinger p\xe5 en klynge, og det kan absorbere millioner av tilkoblinger, noe som gj\xf8r det til et godt valg for utviklere som kobler til Postgres fra serverl\xf8se milj\xf8er. Fremtidig arbeid inkluderer lastbalansering, sesjonspooling, Postgres-h\xf8ytilgjengelighetsadministrasjon og API-er som Postgres bin\xe6r, HTTPS og mye mer. Jos\xe9 Valim og Dashbit-teamet bidro til \xe5 informere Supavisor-designbeslutningene, og det er inspirert av produkter som PgBouncer, Amazon RDS Proxy, Google Cloud SQL Proxy og mer."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35501718",children:"Discussion Service"}),".\nSupabase CEO introduserer Supavisor, en Postgres-tilkoblingspool bygget med Elixir, og fremhever likheten med Pgbouncer og designet for flere leietakere. Supavisors referanser indikerer at den kan h\xe5ndtere h\xf8y gjennomstr\xf8mning mens den bruker 7.8G RAM og ~ 50% CPU p\xe5 en 64vCPU-maskin. Supabase planlegger \xe5 ha Supavisor foran alle sine databaser, og skalere opp databehandling uten nedetid. Discussion Service-brukere ber om tillegg av forberedte uttalelser i transaksjonspooling-modus og forslag om \xe5 bruke Nimble_pool i stedet for Poolboy, mens de roser Elixirs samtidighetst\xf8tte og feiltolerante natur. En Discussion Service-bruker deler arbeidserfaring med Pgbouncer p\xe5 4 vCPU-maskiner, og en annen snakker om deres pool av vanlige Pgbouncers som ruter til forskjellige PostgreSQL-instanser ved hjelp av Googles Cloud SQL-proxy."]}),"\n",(0,i.jsx)(r.h2,{id:"nye-beskyldninger-om-plagiering-mot-roy-lichtenstein",children:"Nye beskyldninger om plagiering mot Roy Lichtenstein."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.theguardian.com/artanddesign/2023/apr/09/new-allegations-of-plagiarism-against-roy-lichtenstein",children:"Original"}),'.\nNye p\xe5stander om plagiering har blitt fremsatt mot Roy Lichtenstein, med en ny film som hevder at hundrevis av verkene hans kan spores til andre kunstnere. Dokumentaren p\xe5st\xe5r at over 30 tegneseriekunstnere ble "appropriert" av grunnleggeren av popkunstbevegelsen, som tjente millioner p\xe5 \xe5 selge verkene sine, mens de originale kunstnerne som ble kopiert, levde trange og til og med fattige liv. Mens noen forsvarer Lichtensteins arbeid som "tilegnelse", kaller kritikerne det tyveri, med "direkte plagiater" sitert sammen med "teknisk og kunstnerisk" overlegne verk kopiert av Lichtenstein.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35501868",children:"Discussion Service"}),".\nNye beskyldninger om plagiat mot Roy Lichtenstein utl\xf8ser diskusjon om etikk, originalitet og hensiktsmessighet i kunstverdenen. Discussion Service-brukere diskuterer om Lichtensteins arbeid er nyskapende eller \xe5penlyst tyveri med minimale endringer. Sp\xf8rsm\xe5l om opphavsrett og immaterielle rettigheter dukker opp, i tillegg til sp\xf8rsm\xe5l om hvilken kulturell verdi tegneseriekunst har i forhold til kunst. Debatten omfatter meninger om kunstens natur, skapelse og verdi i kunstverdenen. De opprinnelige tegneserieskaperne ble ofte sett p\xe5 som d\xe5rlig betalte varer, if\xf8lge innlegget."]})]})}function g(e={}){const{wrapper:r}={...(0,s.R)(),...e.components};return r?(0,i.jsx)(r,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}}}]);